/bin/zsh -lc "python3 - <<'PY'
import json,re
from pathlib import Path
p=Path('/Users/alexandremasmejean/.codex/.chatgpt-projects/g-p-6ad59c015c308191aa21cba63c71a6dc/sites/liberer-la-retraite/dist/corpus/securite-sociale.json')
s=json.loads(p.read_text())
targets={x['number'].replace('L','L. ',1) for x in json.loads(Path('source.json').read_text())}
found=[]
for a in s:
 for para in re.findall(r'<p\\b["'^>]*>(.*?)</p>'"',a['source_xml'],re.S):
  if 'phrase' in para and any(re.search(re.escape(t)+r'(?"'!['"\\d-])',para) for t in targets):
   found.append((a['number'],para))
print('Paragraphes du corpus de sécurité sociale citant un article du lot et une phrase :',len(found))
for n,t in found:
 print(n,t)
PY"

